function configureArchive({ firstUrl, firstName, secondUrl, secondName, destination }) {
  const urls = [firstUrl, secondUrl];
  if (
    !urls.every(
      (url) =>
        typeof url === "string" && /^https:\/\/[a-z0-9.-]+(?::\d{1,5})?\/[^\s#\\]*$/i.test(url),
    ) ||
    firstUrl === secondUrl
  )
    throw new Error("Enter two distinct direct HTTPS file URLs");
  const names = [firstName, secondName];
  if (
    !names.every(
      (name) =>
        typeof name === "string" &&
        name.length > 0 &&
        name.length <= 180 &&
        name === name.trim() &&
        !/[<>:"/\\|?*\u0000-\u001f]/.test(name) &&
        !name.endsWith(".") &&
        !Object.hasOwn(Object.prototype, name),
    ) ||
    firstName.toLowerCase() === secondName.toLowerCase()
  ) {
    throw new Error("Use two distinct filenames without directory components");
  }
  const parts = typeof destination === "string" ? destination.split("/") : [];
  if (
    parts.length < 2 ||
    parts[0] !== "" ||
    destination.length > 512 ||
    !/\.zip$/i.test(parts.at(-1)) ||
    parts
      .slice(1)
      .some((part) => !part || part === "." || part === ".." || /[\\\u0000-\u001f]/.test(part))
  ) {
    throw new Error("Enter a full Dropbox path ending in a ZIP filename");
  }
  return { firstUrl, firstName, secondUrl, secondName, destination, archiveName: parts.at(-1) };
}
const settings = {
  firstUrl: "https://www.rfc-editor.org/rfc/rfc2606.txt",
  firstName: "rfc2606.txt",
  secondUrl: "https://www.rfc-editor.org/rfc/rfc5737.txt",
  secondName: "rfc5737.txt",
  destination: "/images.zip",
};
return [{ json: configureArchive(settings) }];

function validateDownload({ status, size }) {
  if (status !== 200) throw new Error("Both downloads must return a complete file");
  if (!Number.isSafeInteger(size) || size < 0 || size > 1024 * 1024) {
    throw new Error("Each source file must be at most 1 MiB");
  }
}
const configuration = $("Set URLs, filenames, and Dropbox path").first().json;
const item = $input.first();
const files = {};
for (const [key, status] of [
  ["first", $("Download the first file").first().json.statusCode],
  ["second", item.json.statusCode],
]) {
  const bytes = await helpers.getBinaryDataBuffer(0, key);
  validateDownload({ status, size: bytes.length });
  const fileName = configuration[key + "Name"];
  files[key] = {
    ...item.binary[key],
    fileName,
    fileExtension: fileName.includes(".") ? fileName.split(".").at(-1) : "",
  };
}
return [
  {
    json: { path: configuration.destination, archiveName: configuration.archiveName },
    binary: files,
  },
];
